void Weapon::computeBonus(const Object *source, UnsignedInt flags, WeaponBonus &bonus) const
{
	bonus.clear();
	UnsignedInt conditions = source->getWeaponBonusCondition() | flags;
	if (TheWritableGlobalData->m_weaponBonus != NULL)
		TheWritableGlobalData->m_weaponBonus->appendBonuses(conditions, bonus);
	if (m_template->m_extraBonus != NULL)
		m_template->m_extraBonus->appendBonuses(conditions, bonus);
}

