// FUNCTION: BFME2 0x002C9C82 size=185 name=?isWithinTargetPitch@Weapon@@QBE_NPBVObject@@0@Z evidence=N:ledger tier=A
Bool Weapon::isWithinTargetPitch(const Object *source, const Object *victim) const
{
	if (m_pitchLimited)
	{
		const Coord3D *from = source->getPosition();
		const Coord3D *to = victim->getPosition();
		// nearly level targets are always in reach
		if (!(fabs(to->z - from->z) < 10.0f))
		{
			Real lowest, highest;
			source->m_geometryInfo.calcPitches(*from, victim->m_geometryInfo, *to, lowest, highest);

			const WeaponTemplate *tmpl = m_template;
			if (!((lowest >= tmpl->m_minTargetPitch && lowest <= tmpl->m_maxTargetPitch) ||
				(highest >= tmpl->m_minTargetPitch && highest <= tmpl->m_maxTargetPitch) ||
				(lowest <= tmpl->m_minTargetPitch && highest >= tmpl->m_maxTargetPitch)))
				return false;
		}
	}
	return true;
}

