// FUNCTION: BFME2 0x002C9D47 size=174 name=?makeAssistanceRequest@@YAHPAVObject@@PAX@Z evidence=N:ledger tier=A
Int makeAssistanceRequest(Object *obj, void *userData)
{
	AssistanceRequestData *data = (AssistanceRequestData *)userData;
	if (obj == data->m_requestingObject)
		return 1;
	// only units of the asker's own kind answer, and only within range
	if (!obj->getTemplate()->isEquivalentTo(data->m_requestingObject->getTemplate()))
		return 1;
	Real distSqr = obj->rva002615E3(data->m_requestingObject->getPosition());
	if (data->m_requestDistanceSquared < distSqr)
		return 1;

	static NameKeyType key_AssistedTargetingUpdate = TheNameKeyGenerator->nameToKey("AssistedTargetingUpdate");
	AssistedTargetingUpdate *assist = (AssistedTargetingUpdate *)obj->findUpdateModule(key_AssistedTargetingUpdate);
	if (assist != NULL && assist->isFreeToAssist())
		assist->assistAttack(data->m_requestingObject, data->m_victimObject);
	return 1;
}

// FUNCTION: BFME2 0x002C9DF5 size=83 name=?processRequestAssistance@Weapon@@IAEXPBVObject@@PAV2@@Z evidence=N:ledger tier=A
void Weapon::processRequestAssistance(const Object *source, Object *victim)
{
	Player *owner = source->getControllingPlayer();
	if (owner == NULL)
		return;

	AssistanceRequestData data;
	data.m_requestingObject = source;
	data.m_victimObject = victim;
	data.m_requestDistanceSquared = m_template->m_requestAssistRange * m_template->m_requestAssistRange;
	owner->iterateObjects(makeAssistanceRequest, &data);
}

