// ClearNuggets: an override keeps the nuggets it inherited and drops only its own.
void parseClearNuggets(INI * /*ini*/, void *instance, void * /*store*/, const void * /*userData*/)
{
	WeaponTemplate *tmpl = (WeaponTemplate *)instance;
	for (std::list<WeaponEffectNugget *>::iterator it = tmpl->m_nuggets.begin(); it != tmpl->m_nuggets.end(); ++it)
	{
		if (tmpl->m_isOverride && !(*it)->m_addedToOverride)
			continue;
		::delete *it;
	}
	tmpl->m_nuggets.clear();
	tmpl->m_hasDamageNugget = false;
}

