// FUNCTION: BFME2 0x002CCE53 size=128 name=?getPercentReadyToFire@Weapon@@QBEMXZ evidence=N:ledger tier=A
Real Weapon::getPercentReadyToFire() const
{
	switch (computeStatus(NULL))
	{
		case OUT_OF_AMMO:
		case WEAPONSTATUS_4:
			return 0.0f;

		case READY_TO_FIRE:
			return 1.0f;

		case BETWEEN_FIRING_SHOTS:
		case RELOADING_CLIP:
		case WEAPONSTATUS_5:
		{
			UnsignedInt now = TheGameLogic->getFrame();
			UnsignedInt nextShot = m_whenWeCanFireAgain;
			if (now >= nextShot)
				return 1.0f;
			UnsignedInt totalTime = nextShot - m_whenLastReloadStarted;
			if (totalTime == 0)
				return 1.0f;
			UnsignedInt timeLeft = nextShot - now;
			UnsignedInt timeSoFar = totalTime - timeLeft;
			if (timeSoFar >= totalTime)
				return 1.0f;
			return (Real)timeSoFar / (Real)totalTime;
		}
	}
	return 0.0f;
}

