// FUNCTION: BFME2 0x002CE063 size=159 name=?newOverride@WeaponStore@@QAEPAVWeaponTemplate@@PAV2@@Z evidence=N:ledger tier=A
WeaponTemplate *WeaponStore::newOverride(WeaponTemplate *tmpl)
{
	if (tmpl == NULL)
		return NULL;
	if (tmpl->m_isOverride)
		return NULL;

	WeaponTemplate *override = new WeaponTemplate;
	*override = *tmpl;
	override->m_nextTemplate = tmpl;
	override->m_isOverride = true;

	NameKeyType key = override->m_nameKey;
	std::vector<WeaponTemplate *>::iterator it = m_weaponTemplateVector.begin();
	std::vector<WeaponTemplate *>::iterator end = m_weaponTemplateVector.end();
	for (; it != end; ++it)
	{
		if ((*it)->m_nameKey == key)
		{
			m_weaponTemplateVector.erase(it);
			break;
		}
	}
	m_weaponTemplateVector.push_back(override);
	return override;
}

// FUNCTION: BFME2 0x002CE102 size=170 name=?parseWeaponTemplateDefinition@WeaponStore@@SAXPAVINI@@@Z evidence=N:ledger tier=A
void WeaponStore::parseWeaponTemplateDefinition(INI *ini)
{
	AsciiString name;
	name.set(ini->getNextToken());

	WeaponTemplate *tmpl = TheWeaponStore->findWeaponTemplatePrivate(TheNameKeyGenerator->nameToKey(name));
	if (tmpl != NULL)
	{
		if (ini->getLoadType() == INI_LOAD_CREATE_OVERRIDES)
		{
			tmpl = TheWeaponStore->newOverride(tmpl);
		}
		else if (ini->getLoadType() == INI_LOAD_RELOAD)
		{
			TheWeaponStore->rva002CDB0E(tmpl);
			tmpl = TheWeaponStore->newWeaponTemplate(name);
			tmpl->m_unk0x174 = 0;
		}
		else
		{
			return;
		}
	}
	else
	{
		tmpl = TheWeaponStore->newWeaponTemplate(name);
	}
	ini->initFromINI(tmpl, WeaponTemplate::TheWeaponTemplateFieldParseTable);
}

