// FUNCTION: BFME2 0x002CE226 size=90 name=?rva002CE226@Weapon@@QAEXPBVObject@@PBUSavedWeaponState@@@Z evidence=?:placeholder tier=A
void Weapon::rva002CE226(const Object *source, const SavedWeaponState *states)
{
	if (states != NULL)
	{
		for (Int i = 0; i < 6; ++i, ++states)
		{
			if (states->m_templateKey == m_template->m_nameKey)
			{
				m_ammoInClip = states->m_ammoInClip;
				cacheStatus(states->m_status);
				m_whenLastReloadStarted = states->m_whenLastReloadStarted;
				m_whenWeCanFireAgain = states->m_whenWeCanFireAgain;
				return;
			}
		}
	}
	if (m_template->m_instantLoadClipOnActivate)
		loadAmmoNow(source);
	else
		reloadAmmo(source);
}

// FUNCTION: BFME2 0x002CE280 size=138 name=?setClipPercentFull@Weapon@@QAEXM_N@Z evidence=N:ledger tier=A
void Weapon::setClipPercentFull(Real percent, Bool allowReduction)
{
	if (m_template->m_clipSize == 0)
		return;

	Int clipSize = m_template->m_clipSize;
	float scaled = (float)WeaponCRT::floor((double)clipSize * percent);
	Int ammo = Float_To_Long(scaled);
	if (ammo > getRemainingAmmo(false) || (allowReduction && ammo < getRemainingAmmo(false)))
	{
		m_ammoInClip = ammo;
		cacheStatus((WeaponStatus)(getRemainingAmmo(false) != 0));
		m_whenWeCanFireAgain = m_whenLastReloadStarted = TheGameLogic->getFrame();
		rebuildScatterTargets();
	}
}

